from difflib import ndiff
def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    # Read lines from both files
    try:
        with open(file_path1, 'r', newline='') as f1:
            lines1 = f1.readlines()
    except FileNotFoundError:
        raise FileNotFoundError(f"File not found: {file_path1}")
    except Exception as e:
        raise Exception(f"Error reading file {file_path1}: {e}")

    try:
        with open(file_path2, 'r', newline='') as f2:
            lines2 = f2.readlines()
    except FileNotFoundError:
        raise FileNotFoundError(f"File not found: {file_path2}")
    except Exception as e:
        raise Exception(f"Error reading file {file_path2}: {e}")

    # Check if either file is empty
    if not lines1:
        raise ValueError(f"File {file_path1} is empty")
    if not lines2:
        raise ValueError(f"File {file_path2} is empty")

    # Use ndiff to compare the two lists of lines
    diff = list(ndiff(lines1, lines2))

    # Build the report
    report = []
    line_num = 0
    for entry in diff:
        if entry.startswith(' '):
            # No change
            line_num += 1
            report.append({
                'Line Number': line_num,
                'Status': ' ',
                'Content': entry[1:].rstrip('\n\r')
            })
        elif entry.startswith('-'):
            # Line present in first file but not in second
            line_num += 1
            report.append({
                'Line Number': line_num,
                'Status': '-',
                'Content': entry[1:].rstrip('\n\r')
            })
        elif entry.startswith('+'):
            # Line present in second file but not in first
            # Line number stays the same as the previous line in first file
            report.append({
                'Line Number': line_num,
                'Status': '+',
                'Content': entry[1:].rstrip('\n\r')
            })
        # Ignore '?' entries (which ndiff might produce for partial line changes)

    df = pd.DataFrame(report, columns=['Line Number', 'Status', 'Content'])
    return df

